UPDATE public.site_settings SET value = (SELECT jsonb_agg(CASE WHEN item->>'description' = 'Vegetable sourcing for importers and distributors.' THEN jsonb_set(item, '{description}', '"Indian vegetable export supply for international importers and distributors."'::jsonb) ELSE item END ORDER BY ordinal) FROM jsonb_array_elements(value) WITH ORDINALITY AS entries(item, ordinal)) WHERE key = 'categories' AND jsonb_typeof(value) = 'array';
UPDATE public.site_settings SET value = (SELECT jsonb_agg(CASE WHEN item->>'description' = 'Organic agricultural products where certification is available.' THEN jsonb_set(item, '{description}', '"Buyer-requested organic products are subject to availability and verification of certification for the offered product and producer."'::jsonb) ELSE item END ORDER BY ordinal) FROM jsonb_array_elements(value) WITH ORDINALITY AS entries(item, ordinal)) WHERE key = 'categories' AND jsonb_typeof(value) = 'array';
